using JSON3

# Input is the JSON catalog generated by the pinned Pi source, not a live request.
const supported = Dict(
    "openai" => "openai-responses",
    "anthropic" => "anthropic-messages",
    "google" => "google-generative-ai",
    "openrouter" => "openai-completions",
)

function catalog(directory)
    models = NamedTuple[]
    for (provider, api) in supported
        entries = JSON3.read(read(joinpath(directory, "providers", provider * ".json")))
        for value in values(entries)
            value.api == api || continue
            push!(models, (; provider, id=String(value.id), name=String(value.name), api, context=Int(value.contextWindow), maxoutput=Int(value.maxTokens), reasoning=Bool(value.reasoning), images="image" in value.input))
        end
    end
    sort!(models; by=model -> (model.provider, model.id))
end

open(ARGS[2], "w") do io
    models = catalog(ARGS[1])
    println(io, "[")
    for (index, model) in enumerate(models)
        print(io, "  ", JSON3.write(model))
        println(io, index == length(models) ? "" : ",")
    end
    println(io, "]")
end
